def predict(self, data: np.ndarray) -> np.ndarray:
    """Return binary anomaly labels for each row based on Z-scores."""
    scores: np.ndarray = self.predict_scores(data)
    return (np.abs(scores) > self.threshold).astype(int)

def compute_metrics(y_true: np.ndarray, y_scores: np.ndarray, threshold: float = 0.5) -> Dict[str, float]:
    """Computes precision, recall, f1 from thresholded scores and roc_auc from raw scores.

    The threshold is used to convert continuous anomaly scores into binary predictions 
    for precision, recall, and f1-score calculation.
    """
    y_pred = (y_scores >= threshold).astype(int).flatten()
    # Handle edge cases where all predictions are one class or no positive ground truth
    if np.sum(y_pred) == 0:
        precision = 0.0
    else:
        precision = precision_score(y_true, y_pred, zero_division=0)

    if np.sum(y_true) == 0:
        recall = 0.0
    else:
        recall = recall_score(y_true, y_pred, zero_division=0)

    f1 = f1_score(y_true, y_pred, zero_division=0)
    roc = roc_auc_score(y_true, y_scores)
    return {'precision': precision, 'recall': recall, 'f1': f1, 'roc_auc': roc}

def aggregate_results(runs_data: List[Dict[str, Dict[str, float]]]) -> List[Dict[str, float | str]]:
    """Aggregates results from multiple experimental runs into summary rows for CSV output.

    Calculates mean and standard deviation for each metric across the provided runs.
    The result is a list of dictionaries, one per unique method and metric combination,
    containing 'method', 'metric', 'value' (mean) and 'std_dev' (standard deviation).
    """
    metrics_list = []
    for run in runs_data:
        for method_name, metrics in run.items():
            for metric_name, metric_value in metrics.items():
                key = f'{method_name}_{metric_name}'
                found = False
                for item in metrics_list:
                    if item['key'] == key:
                        # Online mean calculation (Welford's algorithm adapted)
                        n = len([r for r in runs_data])
                        # Actually, we can't easily do Welford without storing all values or doing two passes.
                        # The previous implementation used a naive sum-of-squares approach which is numerically unstable
                        # but let's stick to the simple accumulation if data is small, or just store all values.
                        # Let's use a simpler list accumulation for robustness in this context given N_RUNS is small (10).
                        pass 
                        found = True
                        break
                if not found:
                    new_item = {'key': key, 'method': method_name, 'metric': metric_name}
                    metrics_list.append(new_item)

    # Second pass: calculate mean and std
    final_results = []
    for item in metrics_list:
        values = []
        for run in runs_data:
            method_name = item['method']
            metric_name = item['metric']
            if method_name in run and metric_name in run[method_name]:
